function duration(s){return rateDuration(s)} function stationUptime(s){return rateDuration(s)} function rateDurationParts(s){let n=Math.max(0,Math.floor(Number(s)||0)),days=Math.floor(n/86400);n%=86400;const hours=Math.floor(n/3600);n%=3600;const minutes=Math.floor(n/60),seconds=n%60;return{days,hours,minutes,seconds}} function rateDuration(s){const p=rateDurationParts(s),pad=value=>String(value).padStart(2,'0');return`${pad(p.days)}d ${pad(p.hours)}h ${pad(p.minutes)}m ${pad(p.seconds)}s`} function voucherValidity(v){if(!v.expires_at)return'NEVER';const created=Date.parse(v.created_at),expires=Date.parse(v.expires_at);return Number.isFinite(created)&&Number.isFinite(expires)?rateDuration(Math.max(0,Math.round((expires-created)/1000))):'NEVER'} function bytes(v){const n=Number(v||0);return n>1073741824?`${(n/1073741824).toFixed(1)} GB`:n>1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.round(n/1024)} KB`}
