function printManagedVouchers() {
  const ids = new Set(selectedVoucherIds());
  const selected = admin.vouchers.filter(voucher => ids.has(Number(voucher.id)));
  if (!selected.length) return;
  if (selected.some(voucher => !voucher.code_value)) {
    notice('Some selected vouchers have no recoverable code. Deselect those vouchers to print.', true);
    return;
  }
  const tickets = selected.map(voucher => {
    const gateway = admin.zones?.find(zone => Number(zone.id) === Number(voucher.zone_id))?.gateway || '10.0.0.1';
    return `<article><small>${esc(admin.settings?.brand_name || 'VendoOS WiFi')} · VREF #${Number(voucher.id)} · ${esc(voucher.batch_code)}</small><span class="ticket-price">${peso(voucher.price_centavos)}</span><strong>${esc(voucher.code_value)}</strong><span>TIME ${rateDuration(voucher.duration_seconds)}</span><span>VALID ${voucherValidity(voucher)}</span><span>${esc(voucher.status)}</span><div class="ticket-instructions"><em>HOW TO USE VOUCHER CODE</em><br>1. Connect to KINGSLINK WiFi.<br>2. Open your browser and go to http://${esc(gateway)}.<br>3. Enter the voucher code and press Submit.<br><b>ONE TIME USE ONLY. NON REFUNDABLE.</b></div></article>`;
  }).join('');
  openVoucherPrint(tickets);
}

function openVoucherPrint(tickets) {
  const printWindow = window.open('', '_blank');
  if (!printWindow) {
    notice('Allow pop-ups for this site to open the voucher print preview.', true);
    return;
  }
  printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Voucher print templates</title><link rel="stylesheet" href="${location.origin}/assets/voucher-print.css?v=5"></head><body data-template="economy"><header><label>Print template <select id="printTemplate"><option value="economy" selected>Economy · 4 columns · save paper</option><option value="strip">KINGSLINK strips · save paper</option><option value="classic">Classic · 4 columns</option><option value="compact">Compact · 5 columns</option><option value="large">Large cards · 2 columns</option><option value="ticket">WiFi ticket · sample design</option></select></label><button id="printSheet">Print / Save PDF</button><span>Preview your template below. Use A4 paper.</span></header><main>${tickets}</main></body></html>`);
  printWindow.document.close();
  printWindow.document.querySelectorAll('.voucher-ticket').forEach(ticket => {
    const instructions = printWindow.document.createElement('div');
    instructions.className = 'ticket-instructions';
    instructions.textContent = 'Connect to KINGSLINK WiFi. Open http://10.0.0.1 in your browser. Enter the voucher code and press Submit. ONE TIME USE ONLY. NON REFUNDABLE.';
    ticket.append(instructions);
  });
  printWindow.document.getElementById('printTemplate').addEventListener('change', event => {
    printWindow.document.body.dataset.template = event.target.value;
  });
  printWindow.document.getElementById('printSheet').addEventListener('click', () => printWindow.print());
  printWindow.opener = null;
  printWindow.focus();
}
