function createModuleSubmenu(panelId,groups){const panel=$(panelId),all=[...new Set(groups.flatMap(group=>group.elements).filter(Boolean))];if(!panel||groups.length<2||!all.length)return;const nav=document.createElement('nav');nav.className='module-subnav';nav.setAttribute('aria-label','Section navigation');nav.setAttribute('role','tablist');const activate=index=>{groups.forEach((group,i)=>group.elements.filter(Boolean).forEach(element=>{element.classList.toggle('module-section-hidden',i!==index);element.setAttribute('aria-hidden',i===index?'false':'true')}));[...nav.children].forEach((button,i)=>{button.classList.toggle('active',i===index);button.setAttribute('aria-selected',i===index?'true':'false');button.tabIndex=i===index?0:-1});panel.dataset.subsection=groups[index].key||String(index);nav.children[index]?.scrollIntoView({block:'nearest',inline:'nearest'})};groups.forEach((group,index)=>{const button=document.createElement('button');button.type='button';button.className='module-tab';button.dataset.sectionKey=group.key||String(index);button.textContent=group.label;button.setAttribute('role','tab');button.setAttribute('aria-selected','false');button.onclick=()=>activate(index);button.onkeydown=event=>{let next=null;if(event.key==='ArrowRight')next=(index+1)%groups.length;if(event.key==='ArrowLeft')next=(index-1+groups.length)%groups.length;if(event.key==='Home')next=0;if(event.key==='End')next=groups.length-1;if(next===null)return;event.preventDefault();activate(next);nav.children[next].focus()};nav.append(button)});panel.prepend(nav);activate(0)}
