function closeInterfaceConfig(){$('interfaceConfigModal').classList.remove('open')}
function toggleInterfaceStatic(){const form=$('interfaceConfigForm'),mode=form.elements.mode.value,isStatic=mode==='static',isPppoe=mode==='pppoe';$('interfaceStaticFields').hidden=!isStatic;$('interfacePppoeFields').hidden=!isPppoe;form.elements.address.required=isStatic;form.elements.pppoe_username.required=isPppoe;form.elements.mtu.required=isPppoe;form.elements.pppoe_password.required=isPppoe&&form.elements.pppoe_password.dataset.saved!=='1'}
function openInterfaceConfig(name){const item=admin.network?.interfaces?.find(candidate=>candidate.ifname===name);if(!item)return;const config=admin.network?.interface_configs?.[name]||{},form=$('interfaceConfigForm'),dns=Array.isArray(config.dns)?config.dns:[];form.elements.interface.value=name;$('interfaceConfigName').textContent=name;form.elements.mode.value=config.mode||item.address_mode||'dhcp';form.elements.address.value=config.address||(item.ipv4_addresses||[])[0]||'';form.elements.gateway.value=config.gateway||item.default_gateway||'';form.elements.pppoe_username.value=config.pppoe_username||'';form.elements.pppoe_password.value='';form.elements.pppoe_password.dataset.saved=config.pppoe_password_set?'1':'0';form.elements.pppoe_service.value=config.pppoe_service||'';form.elements.mtu.value=Number(config.mtu)||1492;$('interfacePppoePasswordHint').textContent=config.pppoe_password_set?'A password is saved. Leave blank to keep it, or enter a new password.':'Required when PPPoE is configured for the first time.';form.elements.dns1.value=dns[0]||'';form.elements.dns2.value=dns[1]||'';form.elements.cost.value=Number(config.cost)||100;toggleInterfaceStatic();$('interfaceConfigModal').classList.add('open');form.elements.mode.focus()}
$('interfacesBody').addEventListener('click',e=>{const button=e.target.closest('[data-interface-config]');if(button)openInterfaceConfig(button.dataset.interfaceConfig)});
$('interfaceConfigForm').elements.mode.addEventListener('change',toggleInterfaceStatic);
document.querySelectorAll('[data-interface-config-close]').forEach(button=>button.addEventListener('click',closeInterfaceConfig));
$('interfaceConfigModal').addEventListener('click',e=>{if(e.target===$('interfaceConfigModal'))closeInterfaceConfig()});
$('interfaceConfigForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,name=form.elements.interface.value,mode=form.elements.mode.value,payload={mode,address:form.elements.address.value.trim(),gateway:form.elements.gateway.value.trim(),pppoe_username:form.elements.pppoe_username.value.trim(),pppoe_password:form.elements.pppoe_password.value,pppoe_service:form.elements.pppoe_service.value.trim(),mtu:Number(form.elements.mtu.value),dns:[form.elements.dns1.value.trim(),form.elements.dns2.value.trim()].filter(Boolean),cost:Number(form.elements.cost.value)},labels={dhcp:'DHCP',static:'static IP',pppoe:'PPPoE'};if(!confirm(`Apply ${labels[mode]||mode} settings to ${name}? The interface may disconnect briefly.`))return;const submit=form.querySelector('[type="submit"],button:not([type])');submit.disabled=true;try{await api(`/api/admin/network/interfaces/${encodeURIComponent(name)}/config`,{method:'PUT',body:JSON.stringify(payload)});closeInterfaceConfig();notice(`WAN settings for ${name} queued.`);setTimeout(refresh,2500)}catch(error){notice(error.message,true)}finally{submit.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('interfaceConfigModal').classList.contains('open'))closeInterfaceConfig()});

setVoucherBatchCode();if(admin.token){showApp();refresh()}else showLogin();const initial=(location.hash||'#overview').slice(1);switchTab(titles[initial]?initial:'overview');setInterval(()=>{if(admin.token&&!document.hidden)refresh()},15000);

$('useSampleAdCopy').addEventListener('click',()=>{const form=$('settingsForm');form.elements.portal_headline.value='WIFI THAT KEEPS UP.';form.elements.portal_tagline.value='STREAM · STUDY · PLAY';form.elements.portal_announcement.value='Choose a plan. Insert a coin. Get online.';renderPortalEditor({...admin.settings,...Object.fromEntries(new FormData(form))})});

